/*
 * Types shared between the BPF programs and the Go loader.
 * The Go counterparts are generated by bpf2go (see ../gen.go).
 */
#ifndef __SHAWK_H
#define __SHAWK_H

#define TASK_COMM_LEN 16

/* Direction of a flow seen from the local host. */
enum shawk_flow_direction {
	DIR_OUT = 1, /* active open: the local process is the client */
	DIR_IN = 2,  /* passive open: the local process is the server */
};

/*
 * flow_key identifies a bundled flow. Following the in-kernel flow
 * bundling method, the client's ephemeral port is dropped and all
 * connections/datagrams between the same pair of addresses to the same
 * service port are bundled into a single entry. The process identity
 * (cgroup and comm) is part of the key so that different clients on the
 * same host remain distinguishable.
 */
struct shawk_flow_key {
	__u8 laddr[16];               /* local address (IPv4-mapped IPv6 for IPv4) */
	__u8 raddr[16];               /* remote address */
	__u64 cgroup_id;              /* cgroup v2 id of the local process */
	__u32 netns;                  /* network namespace inode number */
	__u16 port;                   /* service (listening) port */
	__u8 direction;               /* enum shawk_flow_direction */
	__u8 proto;                   /* IPPROTO_TCP or IPPROTO_UDP */
	char comm[TASK_COMM_LEN];     /* command name of the local process */
};

struct shawk_flow_stats {
	__u64 bytes_sent;
	__u64 bytes_recv;
	__u64 rtt_sum_us;   /* sum of smoothed RTT samples (TCP) */
	__u32 conns;        /* TCP connections established in the interval */
	__u32 conn_fails;   /* TCP active opens that failed in the interval */
	__u32 open_conns;   /* TCP connections open at the end of the interval */
	__u32 msgs_sent;    /* UDP datagrams sent */
	__u32 msgs_recv;    /* UDP datagrams received */
	__u32 retrans;      /* TCP segments retransmitted */
	__u32 rtt_samples;  /* number of RTT samples */
	__u32 pid;          /* last observed process id */
};

enum shawk_iter_rec_type {
	REC_LISTENER = 1, /* a listening/bound socket (from iter/tcp, iter/udp) */
	REC_OWNER = 2,    /* the owner process of a listening socket (from iter/task_file) */
};

/* Record emitted by the socket iterators through the seq_file. */
struct shawk_iter_rec {
	__u8 addr[16];
	__u64 cgroup_id;
	__u32 netns;
	__u32 pid;
	__u16 port;
	__u8 type;
	__u8 proto;
	char comm[TASK_COMM_LEN];
	__u32 _pad;
	/*
	 * Inode of the socket, which tells apart a listener replaced by another
	 * on the same address; 0 for sockets without a file (of the kernel, or
	 * the subflows of MPTCP).
	 */
	__u64 ino;
};

#define CGROUP_PATH_LEN 512

/* A cgroup v2 created on the host, sent to user space through a ring buffer. */
struct shawk_cgroup_event {
	__u64 id;
	char path[CGROUP_PATH_LEN];
};

#endif /* __SHAWK_H */
